                    if (!Boolean.TRUE.equals(this.safeBool(indicative, "available", false)))
                    {
                        throw new InvalidOrder(((this.id + " createConvertTrade() stock indicative quote unavailable: ") + this.safeString(indicative, "reason", "priceUnavailable"))) ;
                    }
